export interface PaginationState {
  page: number
  size: number
  sort: string
  direction: 'asc' | 'desc'
  totalElements: number
  totalPages: number
}

export function createDefaultPagination(): PaginationState {
  return {
    page: 0,
    size: 20,
    sort: 'createdAt',
    direction: 'desc',
    totalElements: 0,
    totalPages: 0,
  }
}
import type { PaginationState } from '~/types'
import { createDefaultPagination } from '~/types'

export function usePagination(initialState?: Partial<PaginationState>) {
  const state = reactive<PaginationState>({
    ...createDefaultPagination(),
    ...initialState,
  })

  function setPage(page: number) {
    state.page = page
  }

  function setSize(size: number) {
    state.size = size
    state.page = 0
  }

  function setSort(sort: string, direction?: 'asc' | 'desc') {
    if (state.sort === sort && !direction) {
      state.direction = state.direction === 'asc' ? 'desc' : 'asc'
    } else {
      state.sort = sort
      state.direction = direction || 'asc'
    }
    state.page = 0
  }

  function updateFromResponse(totalElements: number, totalPages: number) {
    state.totalElements = totalElements
    state.totalPages = totalPages
  }

  function reset() {
    Object.assign(state, createDefaultPagination())
  }

  return {
    ...toRefs(state),
    setPage,
    setSize,
    setSort,
    updateFromResponse,
    reset,
  }
}
interface ApiError {
  statusCode: number
  message: string
  details?: Record<string, string[]>
}

export function useApiError() {
  function handleError(error: unknown): ApiError {
    const err = error as {
      statusCode?: number
      status?: number
      data?: { message?: string; details?: Record<string, string[]> }
      response?: { status?: number; data?: { message?: string; details?: Record<string, string[]> } }
      message?: string
    }

    const statusCode = err.statusCode || err.status || err.response?.status || 500
    const message =
      err.data?.message ||
      err.response?.data?.message ||
      err.message ||
      'An unexpected error occurred'
    const details = err.data?.details || err.response?.data?.details

    return { statusCode, message, details }
  }

  function getFieldErrors(error: unknown): Record<string, string> {
    const apiError = handleError(error)
    const fieldErrors: Record<string, string> = {}

    if (apiError.details) {
      for (const [field, messages] of Object.entries(apiError.details)) {
        fieldErrors[field] = messages[0]
      }
    }

    return fieldErrors
  }

  function getPermissionDeniedMessage(): string {
    return 'You do not have permission to perform this action.'
  }

  function getNotFoundMessage(resource: string): string {
    return `${resource} not found.`
  }

  function getServerErrorMessage(): string {
    return 'The server is temporarily unavailable. Please try again later.'
  }

  return {
    handleError,
    getFieldErrors,
    getPermissionDeniedMessage,
    getNotFoundMessage,
    getServerErrorMessage,
  }
}
